function minChanges(n, k) {
  // Line up the two binary strings and compare them digit by digit.
  const width = Math.max(n.toString(2).length, k.toString(2).length);
  const a = n.toString(2).padStart(width, '0');
  const b = k.toString(2).padStart(width, '0');
  let count = 0;
  for (let i = 0; i < width; i++) {
    if (a[i] === '0' && b[i] === '1') return -1;
    if (a[i] === '1' && b[i] === '0') count++;
  }
  return count;
}

