function generate(rand, size) {
  const top = size === 'large' ? 1000000 : 64;
  const pick = () => 1 + Math.floor(rand() * top);
  const n = size === 'large' ? top - Math.floor(rand() * (top / 2)) : pick();
  // Half the time k keeps a random part of n's 1 bits, so that k is reachable.
  if (rand() < 0.5) {
    let k = 0;
    for (let bit = 1; bit <= n; bit *= 2) if ((n & bit) && rand() < 0.5) k |= bit;
    return [n, k || n];
  }
  return [n, pick()];
}
